const API=window.FADILA_API_URL,token=localStorage.getItem('token');if(!token)location.href='admin.html';const $=id=>document.getElementById(id);let customers=[],services=[],appointments=[],businessSettings={workingHours:{},dateOverrides:[]},ownerMessages=[],ownerFeedback=[],movingAppointmentId='',timelinePendingChanges={},editingServiceId='',editingDateOverrideKey='';
let existingPushSynced=false;
async function api(path,options={}){options.headers={...(options.headers||{}),Authorization:`Bearer ${token}`};const r=await fetch(API+path,options),d=await r.json().catch(()=>({}));if(r.status===401){localStorage.removeItem('token');location.href='admin.html'}if(!r.ok){const error=new Error(d.error||'حدث خطأ');error.requiresManualEdit=d.requiresManualEdit===true;throw error}return d}
const safe=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));const msg=(id,text,type='')=>{$(id).textContent=text;$(id).className=`message ${type}`};
async function loadCustomers(){const d=await api('/auth/customers');customers=d.data;renderCustomerSelectors();renderCustomersManagement()}
function customerMatches(customer,query){const value=String(query||'').trim().toLocaleLowerCase('ar');return!value||String(customer.name||'').toLocaleLowerCase('ar').includes(value)}
function renderCustomerSelectors(){const activeCustomers=customers.filter(c=>c.active!==false),previousManual=$('manualCustomer').value,manualOptions=activeCustomers.map(c=>`<option value="${c.id}">${safe(c.name)} — ${safe(c.phone)}</option>`).join(''),notificationQuery=$('notificationCustomerSearch')?.value||'',notificationCustomers=activeCustomers.filter(c=>customerMatches(c,notificationQuery)),previousNotification=$('notificationCustomer')?.value||'';$('manualCustomer').innerHTML='<option value="">اختر زبوناً</option>'+manualOptions+'<option value="__walk_in__">زبون لمرة واحدة (بدون حساب)</option>';if([...$('manualCustomer').options].some(option=>option.value===previousManual))$('manualCustomer').value=previousManual;$('notificationCustomer').innerHTML='<option value="">اختر زبوناً</option><option value="__all__">📣 جميع الزبائن</option>'+notificationCustomers.map(c=>`<option value="${c.id}">${safe(c.name)} — ${safe(c.phone)}</option>`).join('');if([...$('notificationCustomer').options].some(option=>option.value===previousNotification))$('notificationCustomer').value=previousNotification;updateManualCustomerFields()}
function updateManualCustomerFields(){const oneOff=$('manualCustomer').value==='__walk_in__';$('manualOneOffFields').classList.toggle('hidden',!oneOff);$('manualCustomerName').required=oneOff;$('manualCustomerPhone').required=oneOff}
function renderCustomersManagement(){const query=$('manageCustomerSearch')?.value||'',filtered=customers.filter(c=>customerMatches(c,query)),select=$('manageCustomerSelect'),previous=select.value;select.innerHTML='<option value="">اختر زبوناً</option>'+filtered.map(c=>`<option value="${safe(c.id)}">${safe(c.name)}${c.active===false?' — محظور':''}</option>`).join('');if(filtered.some(c=>String(c.id)===previous))select.value=previous;const customer=customers.find(c=>String(c.id)===select.value);if(!customer){$('customersManagement').innerHTML='';return}$('customersManagement').innerHTML=`<article class="customer-management-item ${customer.active===false?'is-blocked':''}"><div class="customer-management-summary"><div><strong>${safe(customer.name)}</strong><span>${safe(customer.phone)} · ${customer.active===false?'محظور':'نشط'}</span></div></div><div class="customer-management-fields"><label>اسم المستخدم<input id="customer-username-${customer.id}" value="${safe(customer.username)}" autocomplete="off"></label><label>رقم الهاتف<input id="customer-phone-${customer.id}" type="tel" inputmode="numeric" maxlength="10" value="${safe(customer.phone)}" autocomplete="tel"></label></div><div class="customer-management-actions"><button type="button" onclick="updateCustomerDetails('${customer.id}')">حفظ</button><button type="button" class="secondary" onclick="toggleCustomerStatus('${customer.id}',${customer.active===false})">${customer.active===false?'إلغاء الحظر':'حظر'}</button><button type="button" class="danger" onclick="deleteCustomer('${customer.id}')">حذف</button></div><div class="customer-password-reset"><label>كلمة مرور جديدة<input id="customer-password-${customer.id}" type="password" minlength="6" autocomplete="new-password" placeholder="اتركها فارغة لعدم التغيير"></label><div class="customer-password-actions"><button type="button" class="secondary compact" onclick="toggleCustomerPasswordVisibility('${customer.id}',this)">إظهار</button><button type="button" onclick="resetCustomerPassword('${customer.id}')">تغيير كلمة المرور</button></div></div></article>`}
async function updateCustomerDetails(id){try{await api('/auth/customers/'+id,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({username:$('customer-username-'+id).value,phone:$('customer-phone-'+id).value})});await loadCustomers();$('manageCustomerSelect').value=id;renderCustomersManagement();msg('manageCustomerMessage','تم حفظ بيانات الزبون','success')}catch(e){msg('manageCustomerMessage',e.message,'error')}}
async function resetCustomerPassword(id){const input=$('customer-password-'+id),password=input.value;if(password.length<6)return msg('manageCustomerMessage','كلمة المرور الجديدة يجب أن تحتوي على 6 أحرف على الأقل','error');try{await api('/auth/customers/'+id,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({password})});input.value='';msg('manageCustomerMessage','تم تغيير كلمة المرور','success')}catch(e){msg('manageCustomerMessage',e.message,'error')}}
function toggleCustomerPasswordVisibility(id,button){const input=$('customer-password-'+id),visible=input.type==='password';input.type=visible?'text':'password';button.textContent=visible?'إخفاء':'إظهار';button.setAttribute('aria-pressed',String(visible))}
async function toggleCustomerStatus(id,activate){const customer=customers.find(c=>String(c.id)===id),action=activate?'إلغاء حظر':'حظر';if(!confirm(`${action} حساب ${customer?.name||''}؟`))return;try{await api(`/auth/customers/${id}/status`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({active:activate})});await loadCustomers();$('manageCustomerSelect').value=id;renderCustomersManagement();msg('manageCustomerMessage',activate?'تم إلغاء حظر الحساب':'تم حظر الحساب','success')}catch(e){msg('manageCustomerMessage',e.message,'error')}}
async function deleteCustomer(id){const customer=customers.find(c=>String(c.id)===id);if(!confirm(`حذف حساب ${customer?.name||''} نهائياً؟ سيتم الاحتفاظ بالمواعيد السابقة كسجل، لكن لا يمكن التراجع عن حذف الحساب.`))return;try{await api('/auth/customers/'+id,{method:'DELETE'});$('manageCustomerSelect').value='';await loadCustomers();msg('manageCustomerMessage','تم حذف الحساب','success')}catch(e){msg('manageCustomerMessage',e.message,'error')}}
async function createCustomer(){try{await api('/auth/customers',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:$('customerName').value,phone:$('customerPhone').value,username:$('customerUsername').value,password:$('customerPassword').value})});msg('customerMessage','تم إنشاء الحساب بنجاح','success');['customerName','customerPhone','customerUsername','customerPassword'].forEach(id=>$(id).value='');await loadCustomers()}catch(e){msg('customerMessage',e.message,'error')}}
async function loadServices(){services=await api('/services');const options='<option value="">اختر خدمة</option>'+services.map(s=>`<option value="${safe(s.name)}">${safe(s.name)} — ${s.duration} دقيقة</option>`).join('');$('manualService').innerHTML=options;$('services').innerHTML=services.map(s=>`<div class="appointment row-between service-management-item"><span>${safe(s.name)} — ₪${s.price}، ${s.duration} دقيقة</span><div class="service-management-actions"><button type="button" class="secondary compact" onclick="editService('${s._id}')">تعديل</button><button type="button" class="danger compact" onclick="deleteService('${s._id}')">حذف</button></div></div>`).join('');if(appointments.length){renderAppointments();decorateAllAppointmentDates()}}
async function addService(){const payload={name:$('serviceName').value.trim(),price:Number($('servicePrice').value),duration:Number($('serviceDuration').value)};try{if(editingServiceId){await api('/services/'+editingServiceId,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});msg('serviceMessage','تم تحديث الخدمة','success')}else{await api('/services',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});msg('serviceMessage','تمت إضافة الخدمة','success')}cancelServiceEdit();await loadServices()}catch(e){msg('serviceMessage',e.message,'error')}}
function editService(id){const service=services.find(item=>item._id===id);if(!service)return;editingServiceId=id;$('serviceName').value=service.name;$('servicePrice').value=service.price;$('serviceDuration').value=service.duration;$('addService').textContent='حفظ التعديل';$('cancelServiceEdit').classList.remove('hidden');$('serviceName').scrollIntoView({behavior:'smooth',block:'center'});$('serviceName').focus()}
function cancelServiceEdit(){editingServiceId='';$('serviceName').value='';$('servicePrice').value='';$('serviceDuration').value='';$('addService').textContent='إضافة خدمة';$('cancelServiceEdit').classList.add('hidden')}
async function deleteService(id){if(confirm('هل تريد حذف الخدمة؟')){try{await api('/services/'+id,{method:'DELETE'});if(editingServiceId===id)cancelServiceEdit();await loadServices();msg('serviceMessage','تم حذف الخدمة','success')}catch(e){msg('serviceMessage',e.message,'error')}}}
async function loadSlots(){const date=$('manualDate').value,service=$('manualService').value;if(!date||!service)return;const d=await api(`/appointments/available/${date}?service=${encodeURIComponent(service)}`);$('manualTime').innerHTML='<option value="">اختر ساعة</option>'+d.availableSlots.map(t=>`<option>${t}</option>`).join('');$('manualTime').disabled=!d.availableSlots.length}
async function createAppointment(){const oneOff=$('manualCustomer').value==='__walk_in__',customerId=$('manualCustomer').value,name=$('manualCustomerName').value.trim(),phone=$('manualCustomerPhone').value.replace(/\D/g,'');if(oneOff&&name.length<2)return msg('manualMessage','يرجى إدخال اسم العميل','error');if(oneOff&&!/^05\d{8}$/.test(phone))return msg('manualMessage','يرجى إدخال رقم هاتف صحيح بصيغة 05XXXXXXXX','error');if(!oneOff&&!customerId)return msg('manualMessage','يرجى اختيار العميل','error');try{const result=await api('/appointments',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({oneOff,customerId:oneOff?'':customerId,customerName:name,customerPhone:phone,service:$('manualService').value,date:$('manualDate').value,time:$('manualTime').value})});msg('manualMessage','تم إنشاء الموعد','success');await loadAppointments();if(result.data?.customerPhone)offerWhatsAppReminder(result.data,{},true);if(oneOff){$('manualCustomer').value='';$('manualCustomerName').value='';$('manualCustomerPhone').value='';updateManualCustomerFields()}}catch(e){msg('manualMessage',e.message,'error')}}
const statusOptions=a=>['pending','confirmed','cancelled','completed','no-show'].map(s=>`<option value="${s}" ${a.status===s?'selected':''}>${statusLabel(s)}</option>`).join('');
function getTodayInJerusalem(){return new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Jerusalem',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date())}

function renderOwnerOverview(){
 const today=getTodayInJerusalem(),todayLabel=new Intl.DateTimeFormat('ar',{timeZone:'Asia/Jerusalem',weekday:'long',day:'numeric',month:'long'}).format(new Date());
 $('ownerOverviewDate').textContent=todayLabel;
 $('overviewTodayCount').textContent=String(appointments.filter(item=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Jerusalem'}).format(new Date(item.date))===today&&item.status!=='cancelled').length);
 $('overviewPendingCount').textContent=String(appointments.filter(item=>item.status==='pending').length);
 $('overviewUnreadCount').textContent=String(ownerMessages.filter(item=>!item.readAt).length);
 $('overviewFeedbackCount').textContent=String(ownerFeedback.length);
 const currentTime=new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Jerusalem',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(new Date());
 const upcoming=appointments.filter(item=>{
  if(!['pending','confirmed'].includes(item.status))return false;
  const day=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Jerusalem'}).format(new Date(item.date));
  return day>today||(day===today&&String(item.time||'')>=currentTime);
 }).sort((a,b)=>{
  const aDay=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Jerusalem'}).format(new Date(a.date)),bDay=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Jerusalem'}).format(new Date(b.date));
  return aDay.localeCompare(bDay)||String(a.time||'').localeCompare(String(b.time||''));
 });
 const next=upcoming[0];
 $('overviewNextName').textContent=next?String(next.customerName||'زبون'): 'لا يوجد موعد قادم';
 $('overviewNextService').textContent=next?String(next.service||''):'';
 $('overviewNextTime').textContent=next?new Intl.DateTimeFormat('ar',{timeZone:'Asia/Jerusalem',day:'numeric',month:'short'}).format(new Date(next.date))+' · '+String(next.time||''):'';
}
async function loadAppointments(){const d=await api('/appointments');appointments=d.data;renderAppointments();decorateAllAppointmentDates();renderOneOffReminders();renderOwnerOverview()}
function oneOffReminderUrl(appointment){const phone=String(appointment.customerPhone||'').replace(/\D/g,'').replace(/^0/,'972');if(!phone)return'';const date=new Intl.DateTimeFormat('ar',{timeZone:'Asia/Jerusalem',day:'numeric',month:'long'}).format(new Date(appointment.date));const text=`مرحباً ${appointment.customerName} 👋\nتذكير بموعدك اليوم في Fadila Barber 💈\nالخدمة: ${appointment.service}\nالتاريخ: ${date}\nالساعة: ${appointment.time}\nننتظرك بكل سرور 😊`;return`https://wa.me/${phone}?text=${encodeURIComponent(text)}`}
function renderOneOffReminders(){const today=getTodayInJerusalem(),now=Date.now(),reminders=appointments.filter(a=>!a.customer&&a.customerPhone&&['pending','confirmed'].includes(a.status)&&new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Jerusalem'}).format(new Date(a.date))===today&&new Date(a.date).getTime()>now).sort((a,b)=>new Date(a.date)-new Date(b.date));const list=$('oneOffReminders'),summary=$('oneOffReminderSummary');summary.textContent=reminders.length?`${reminders.length} موعد قادم اليوم لزبائن لمرة واحدة. افتح الرسالة وأرسلها من WhatsApp.`:'لا توجد مواعيد قادمة لزبائن لمرة واحدة اليوم';list.innerHTML=reminders.map(a=>{const url=oneOffReminderUrl(a);return`<article class="appointment compact-appointment ${safe(a.status)} one-off-reminder-item"><div class="appointment-summary"><time datetime="${safe(a.date)}">${safe(a.time)}</time><div class="appointment-summary-text"><strong>${safe(a.customerName)}</strong><span>${safe(a.service)}</span></div><a class="secondary compact one-off-reminder-button" href="${safe(url)}" target="_blank" rel="noopener noreferrer">فتح رسالة WhatsApp</a></div></article>`}).join('')}
function renderAppointments(){const date=$('filterDate').value;const list=date?appointments.filter(a=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Jerusalem'}).format(new Date(a.date))===date):appointments;$('appointments').innerHTML=list.length?list.map(a=>{const appointmentDate=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Jerusalem'}).format(new Date(a.date)),serviceOptions=(services.some(s=>s.name===a.service)?'':`<option value="${safe(a.service)}" selected>${safe(a.service)}</option>`)+services.map(s=>`<option value="${safe(s.name)}" ${s.name===a.service?'selected':''}>${safe(s.name)} — ${s.duration} دقيقة</option>`).join('');return`<article class="appointment compact-appointment ${a.status}" id="appointment-${a._id}"><div class="appointment-summary"><time>${safe(a.time)}</time><div class="appointment-summary-text"><strong>${safe(a.customerName)}</strong><span>${safe(a.service)}</span></div><span class="appointment-status">${safe(statusLabel(a.status))}</span><button class="secondary appointment-edit-toggle" type="button" onclick="toggleAppointmentEditor('${a._id}',this)" aria-expanded="false">تعديل</button></div>${a.notes?`<div class="appointment-customer-note"><strong>ملاحظة من العميل</strong><p>${safe(a.notes)}</p></div>`:'' }<div class="appointment-editor hidden" id="editor-${a._id}"><div class="appointment-schedule-edit"><div class="grid-two appointment-date-time owner-date-time-pair"><label>التاريخ<input id="date-${a._id}" type="date" value="${appointmentDate}"></label><label>الساعة<input id="time-${a._id}" type="time" value="${safe(a.time)}"></label></div><label class="appointment-service-field">نوع الخدمة<select id="service-${a._id}">${serviceOptions}</select></label><label class="appointment-status-field">الحالة<select id="status-${a._id}">${statusOptions(a)}</select></label><label class="appointment-notes-field">ملاحظة العميل<textarea id="notes-${a._id}" maxlength="500" rows="2">${safe(a.notes||'')}</textarea></label></div><div class="appointment-actions"><button onclick="updateAppointment('${a._id}')">حفظ وإرسال إشعار</button><button class="danger" onclick="deleteAppointment('${a._id}')">حذف الموعد</button></div></div></article>`}).join(''):'<p class="muted">لا توجد مواعيد</p>'}
function updateAppointmentFilterControls(){$('showAllAppointments').textContent=$('filterDate').value?'عرض كل المواعيد':'عرض مواعيد اليوم';$('timelineEditorButton').disabled=!$('filterDate').value}
function decorateAllAppointmentDates(){appointments.forEach(a=>{const card=$('appointment-'+a._id),detail=card?.querySelector('.appointment-summary-text span');if(!$('filterDate').value&&detail)detail.textContent+=` · ${new Date(a.date).toLocaleDateString('ar',{timeZone:'Asia/Jerusalem'})}`;if(card&&a.changeRequest?.status==='pending'&&!card.querySelector('.owner-change-request'))card.querySelector('.appointment-summary').insertAdjacentHTML('afterend',`<div class="owner-change-request"><strong>طلب تعديل من الزبون</strong><p><b>الخدمة:</b> ${safe(a.changeRequest.requestedService||'غير محددة')} · <b>التاريخ:</b> ${safe(a.changeRequest.requestedDate||'غير محدد')} · <b>الساعة:</b> ${safe(a.changeRequest.requestedTime||'غير محددة')}</p>${a.changeRequest.text?`<p>${safe(a.changeRequest.text)}</p>`:''}<div class="change-request-actions"><button type="button" onclick="resolveChangeRequest('${a._id}','approved')">موافقة وتحديث</button><button type="button" class="danger" onclick="resolveChangeRequest('${a._id}','rejected')">رفض</button><button type="button" class="secondary" onclick="openPartialChangeEdit('${a._id}')">تعديل جزئي</button></div></div>`)})}
function toggleAllAppointments(){if($('filterDate').value)$('filterDate').value='';else $('filterDate').value=getTodayInJerusalem();updateAppointmentFilterControls();renderAppointments();decorateAllAppointmentDates()}
function statusLabel(status){return({pending:'بانتظار الموافقة',confirmed:'مؤكد',cancelled:'ملغي',completed:'مكتمل','no-show':'لم يحضر'})[status]||status}
function toggleAppointmentEditor(id,button){const editor=$('editor-'+id),open=editor.classList.contains('hidden');editor.classList.toggle('hidden',!open);button.textContent=open?'إغلاق':'تعديل';button.setAttribute('aria-expanded',String(open))}
function whatsappReminderUrl(appointment,changes={},newAppointment=false){if(!appointment?.customerPhone)return'';const phone=String(appointment.customerPhone).replace(/\D/g,'').replace(/^0/,'972'),service=changes.service||appointment.service,dateValue=changes.date||new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Jerusalem'}).format(new Date(appointment.date)),time=changes.time||appointment.time,date=new Date(`${dateValue}T12:00:00`).toLocaleDateString('ar');const intro=newAppointment?'نؤكد لك موعدك في Fadila Barber 💈':'نذكّرك بموعدك المحدّث في Fadila Barber 💈',reminder=`مرحباً ${appointment.customerName} 👋\n${intro}\nالخدمة: ${service}\nالتاريخ: ${date}\nالساعة: ${time}\nننتظرك بكل سرور 😊`;return`https://wa.me/${phone}?text=${encodeURIComponent(reminder)}`}
function offerWhatsAppReminder(appointment,changes={},newAppointment=false){const url=whatsappReminderUrl(appointment,changes,newAppointment),question=newAppointment?'تم إنشاء الموعد. هل تريد فتح واتساب برسالة تأكيد جاهزة للعميل؟':'تم إرسال إشعار للزبون عبر التطبيق. هل تريد أيضاً إرسال تذكير عبر واتساب؟';if(url&&confirm(question))location.href=url}
async function updateAppointment(id){const appointment=appointments.find(item=>item._id===id),changes={service:$('service-'+id).value,date:$('date-'+id).value,time:$('time-'+id).value,status:$('status-'+id).value,notes:$('notes-'+id).value};try{await api('/appointments/'+id,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(changes)});await loadAppointments();await loadOwnerMessages();offerWhatsAppReminder(appointment,changes)}catch(e){alert(e.message)}}
async function deleteAppointment(id){const a=appointments.find(x=>x._id===id);if(!a||!confirm(`هل تريد حذف موعد ${a.customerName}؟ سيتلقى الزبون إشعار إلغاء.`))return;try{await api('/appointments/'+id,{method:'DELETE'});await loadAppointments()}catch(e){alert(e.message)}}
async function resolveChangeRequest(id,decision){const label=decision==='approved'?'الموافقة وتحديث الموعد':'الرفض',appointment=appointments.find(item=>item._id===id),changes=decision==='approved'?{service:appointment?.changeRequest?.requestedService,date:appointment?.changeRequest?.requestedDate,time:appointment?.changeRequest?.requestedTime}:{};if(!confirm(`تأكيد ${label}؟`))return;try{await api(`/appointments/${id}/change-request`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({decision})});await loadAppointments();await loadOwnerMessages();if(decision==='approved')offerWhatsAppReminder(appointment,changes)}catch(e){alert(e.message);if(e.requiresManualEdit)openPartialChangeEdit(id)}}
function openMessageAppointmentEditor(id,messageId,forceOpen=false){const appointment=appointments.find(item=>item._id===id),editor=$('message-appointment-editor-'+messageId);if(!appointment||!editor)return alert('لم يتم العثور على الموعد');if(!forceOpen&&!editor.classList.contains('hidden')){editor.classList.add('hidden');return}const hasPendingChange=appointment.changeRequest?.status==='pending',service=hasPendingChange&&appointment.changeRequest.requestedService?appointment.changeRequest.requestedService:appointment.service,date=hasPendingChange&&appointment.changeRequest.requestedDate?appointment.changeRequest.requestedDate:appointmentDateString(appointment),time=hasPendingChange&&appointment.changeRequest.requestedTime?appointment.changeRequest.requestedTime:appointment.time,notes=appointment.notes||(hasPendingChange?appointment.changeRequest.text:'')||'',serviceOptions=(services.some(item=>item.name===service)?'':`<option value="${safe(service)}" selected>${safe(service)}</option>`)+services.map(item=>`<option value="${safe(item.name)}" ${item.name===service?'selected':''}>${safe(item.name)} — ${item.duration} دقيقة</option>`).join('');editor.innerHTML=`<div class="message-appointment-edit-grid"><div class="message-edit-schedule"><label>التاريخ<input id="message-edit-date-${messageId}" type="date" value="${safe(date)}"></label><label>الساعة<input id="message-edit-time-${messageId}" type="time" value="${safe(time)}"></label></div><label class="message-edit-full">نوع الخدمة<select id="message-edit-service-${messageId}">${serviceOptions}</select></label><label class="message-edit-full">الحالة<select id="message-edit-status-${messageId}">${statusOptions(appointment)}</select></label><label class="message-edit-full">ملاحظة<textarea id="message-edit-notes-${messageId}" maxlength="500" rows="3">${safe(notes)}</textarea></label></div><div class="message-appointment-edit-actions"><button type="button" onclick="saveMessageAppointmentEdit('${id}','${messageId}')">حفظ التعديل</button><button type="button" class="secondary" onclick="closeMessageAppointmentEditor('${messageId}')">إغلاق</button></div>`;editor.classList.remove('hidden')}
function closeMessageAppointmentEditor(messageId){$('message-appointment-editor-'+messageId)?.classList.add('hidden')}
async function saveMessageAppointmentEdit(id,messageId){const appointment=appointments.find(item=>item._id===id);if(!appointment)return alert('لم يتم العثور على الموعد');const changes={service:$('message-edit-service-'+messageId).value,date:$('message-edit-date-'+messageId).value,time:$('message-edit-time-'+messageId).value,status:$('message-edit-status-'+messageId).value,notes:$('message-edit-notes-'+messageId).value};try{await api('/appointments/'+id,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(changes)});await loadAppointments();await loadOwnerMessages();offerWhatsAppReminder(appointment,changes)}catch(error){alert(error.message)}}
function openPartialChangeEdit(id){const appointment=appointments.find(item=>item._id===id);if(!appointment)return alert('لم يتم العثور على الموعد');if(!$('ownerMessagesPanel').classList.contains('hidden')){const message=ownerMessages.find(item=>messageAppointmentId(item)===id);if(message){openMessageAppointmentEditor(id,message._id,true);return}}const requestedDate=appointment.changeRequest?.requestedDate||appointmentDateString(appointment);if($('filterDate').value!==requestedDate){$('filterDate').value=requestedDate;updateAppointmentFilterControls();renderAppointments();decorateAllAppointmentDates()}const card=$('appointment-'+id),toggle=card?.querySelector('.appointment-edit-toggle'),editor=$('editor-'+id),notes=$('notes-'+id);closeOwnerMessages();if(toggle&&editor?.classList.contains('hidden'))toggleAppointmentEditor(id,toggle);if(appointment.changeRequest?.status==='pending'){if(appointment.changeRequest.requestedDate)$('date-'+id).value=appointment.changeRequest.requestedDate;if(appointment.changeRequest.requestedTime)$('time-'+id).value=appointment.changeRequest.requestedTime;if(appointment.changeRequest.requestedService)$('service-'+id).value=appointment.changeRequest.requestedService;if(notes&&appointment.changeRequest.text&&!notes.value)notes.value=appointment.changeRequest.text}if(notes){notes.placeholder='اكتب للزبون تفاصيل التعديل الذي تقترحه';notes.focus()}card?.scrollIntoView({behavior:'smooth',block:'center'})}
const TIMELINE_START=7,TIMELINE_END=24,TIMELINE_PX_PER_HOUR=72;
function minutesFromTime(time){const [hours,minutes]=time.split(':').map(Number);return hours*60+minutes}
function timeFromMinutes(total){return`${String(Math.floor(total/60)).padStart(2,'0')}:${String(total%60).padStart(2,'0')}`}
function appointmentDateString(a){return new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Jerusalem'}).format(new Date(a.date))}
function appointmentsForSelectedDate(){const date=$('filterDate').value;return appointments.flatMap(a=>{const pending=timelinePendingChanges[a._id]||{},appointmentDate=pending.date||appointmentDateString(a);return appointmentDate===date&&a.status!=='cancelled'?[{...a,...pending,date:appointmentDate}]:[]})}
function openTimeline(){const date=$('filterDate').value;if(!date)return alert('يرجى اختيار تاريخ');$('timelineDateLabel').textContent=new Date(`${date}T12:00:00`).toLocaleDateString('ar',{weekday:'long',day:'numeric',month:'long',year:'numeric'});renderTimeline();updateTimelinePendingMessage();$('timelineModal').classList.remove('hidden');document.body.classList.add('timeline-open');const first=appointmentsForSelectedDate().sort((a,b)=>a.time.localeCompare(b.time))[0];$('timelineScroll').scrollTop=first?Math.max(0,(minutesFromTime(first.time)-TIMELINE_START*60)/60*TIMELINE_PX_PER_HOUR-70):0}
function closeTimeline(){$('timelineModal').classList.add('hidden');closeMoveDatePanel();document.body.classList.remove('timeline-open')}
function renderTimeline(){const grid=$('timelineGrid'),height=(TIMELINE_END-TIMELINE_START)*TIMELINE_PX_PER_HOUR,totalTicks=(TIMELINE_END-TIMELINE_START)*12;grid.style.height=`${height}px`;const ticks=Array.from({length:totalTicks+1},(_,i)=>{const totalMinutes=TIMELINE_START*60+i*5,isHour=i%12===0,isQuarter=i%3===0,label=isHour?`${String(Math.floor(totalMinutes/60)).padStart(2,'0')}:00`:'';return`<div class="timeline-tick ${isHour?'hour':isQuarter?'quarter':'minor'}" style="top:${i*TIMELINE_PX_PER_HOUR/12}px">${label?`<span>${label}</span>`:''}</div>`}).join('');grid.innerHTML=ticks+appointmentsForSelectedDate().map(a=>{const start=minutesFromTime(a.time),itemHeight=Math.max(30,Number(a.duration||30)/60*TIMELINE_PX_PER_HOUR),top=Math.max(0,Math.min(height-itemHeight,(start-TIMELINE_START*60)/60*TIMELINE_PX_PER_HOUR)),pending=Boolean(timelinePendingChanges[a._id]);return`<div class="timeline-appointment ${a.status}${pending?' has-pending-change':''}" data-id="${a._id}" style="top:${top}px;height:${itemHeight}px"><div class="timeline-appointment-text"><strong>${safe(a.time)} · ${safe(a.customerName)}</strong><span>${safe(a.service)} · ${safe(a.duration)} دقيقة</span></div><div class="timeline-appointment-buttons"><button type="button" data-move-day-id="${a._id}">نقل ليوم آخر</button><button type="button" data-edit-id="${a._id}">تعديل</button></div><div class="timeline-resize-handle" role="separator" aria-label="اسحب لتغيير مدة الموعد"></div></div>`}).join('');grid.querySelectorAll('.timeline-appointment').forEach(enableTimelineDrag);grid.querySelectorAll('[data-move-day-id]').forEach(button=>button.addEventListener('click',event=>{event.stopPropagation();moveAppointmentToAnotherDay(button.dataset.moveDayId)}));grid.querySelectorAll('[data-edit-id]').forEach(button=>button.addEventListener('click',event=>{event.stopPropagation();closeTimeline();const id=button.dataset.editId,card=$('appointment-'+id),toggle=card?.querySelector('.appointment-edit-toggle');if(toggle&&$('editor-'+id).classList.contains('hidden'))toggleAppointmentEditor(id,toggle);card?.scrollIntoView({behavior:'smooth',block:'center'})}))}
function stageTimelineChange(id,updates){const appointment=appointments.find(item=>item._id===id);if(!appointment)return;const next={...(timelinePendingChanges[id]||{}),...updates},originalDate=appointmentDateString(appointment);if(next.date===originalDate)delete next.date;if(next.time===appointment.time)delete next.time;if(Number(next.duration)===Number(appointment.duration))delete next.duration;if(Object.keys(next).length)timelinePendingChanges[id]=next;else delete timelinePendingChanges[id];updateTimelinePendingMessage();renderTimeline()}
function updateTimelinePendingMessage(text=''){const count=Object.keys(timelinePendingChanges).length,button=$('applyTimelineChanges');$('timelineMessage').textContent=text||(count?`تم تعديل ${count} موعد. يمكنك متابعة التعديلات؛ أرسلها عند الانتهاء.`: '');$('timelineMessage').className=count?'message success':'message';button.classList.toggle('hidden',!count);button.disabled=false}
function moveAppointmentToAnotherDay(id){const appointment=appointments.find(item=>item._id===id);if(!appointment)return;movingAppointmentId=id;const pending=timelinePendingChanges[id]||{};$('moveDateCustomer').textContent=`${appointment.customerName} · ${pending.time||appointment.time}`;$('moveDateInput').value=pending.date||$('filterDate').value;$('moveDateInput').min=getTodayInJerusalem();$('moveDatePanel').classList.remove('hidden');$('moveDateInput').focus()}
function closeMoveDatePanel(){movingAppointmentId='';$('moveDatePanel').classList.add('hidden')}
function confirmMoveDate(){const appointment=appointments.find(item=>item._id===movingAppointmentId),newDate=$('moveDateInput').value,currentDate=(timelinePendingChanges[movingAppointmentId]||{}).date||$('filterDate').value;if(!appointment||!newDate)return alert('يرجى اختيار تاريخ جديد');if(newDate===currentDate)return alert('يرجى اختيار يوم آخر');const id=movingAppointmentId,pending=timelinePendingChanges[id]||{};closeMoveDatePanel();stageTimelineChange(id,{...pending,date:newDate});updateTimelinePendingMessage(`تم تجهيز نقل موعد ${appointment.customerName}. اضغط زر التأكيد أسفل النافذة لإرسال التغيير والإشعار.`)}
function enableTimelineDrag(block){block.addEventListener('pointerdown',event=>{if(event.target.closest('button'))return;event.preventDefault();const resizing=Boolean(event.target.closest('.timeline-resize-handle')),startY=event.clientY,startValue=resizing?parseFloat(block.style.height):parseFloat(block.style.top),gridHeight=parseFloat($('timelineGrid').style.height),startTop=parseFloat(block.style.top),startHeight=parseFloat(block.style.height),snap=TIMELINE_PX_PER_HOUR/12;block.setPointerCapture(event.pointerId);block.classList.add('dragging');const move=moveEvent=>{const delta=moveEvent.clientY-startY;if(resizing){const maxHeight=Math.max(15,gridHeight-startTop),raw=Math.max(25,Math.min(maxHeight,startValue+delta)),height=Math.round(raw/snap)*snap;block.style.height=`${height}px`}else{const maxTop=gridHeight-startHeight,raw=Math.max(0,Math.min(maxTop,startValue+delta));block.style.top=`${Math.round(raw/snap)*snap}px`}};const finish=endEvent=>{block.removeEventListener('pointermove',move);block.removeEventListener('pointerup',finish);block.removeEventListener('pointercancel',finish);block.classList.remove('dragging');if(endEvent.type==='pointercancel'){renderTimeline();return}if(resizing){const duration=Math.max(25,Math.round(parseFloat(block.style.height)/snap)*5);stageTimelineChange(block.dataset.id,{duration})}else{const minutes=TIMELINE_START*60+Math.round(parseFloat(block.style.top)/snap)*5;stageTimelineChange(block.dataset.id,{time:timeFromMinutes(minutes)})}};block.addEventListener('pointermove',move);block.addEventListener('pointerup',finish);block.addEventListener('pointercancel',finish)})}
async function applyTimelineChanges(){const ids=Object.keys(timelinePendingChanges);if(!ids.length)return;const button=$('applyTimelineChanges'),reminders=[];button.disabled=true;updateTimelinePendingMessage('جارٍ حفظ التغييرات وإرسال الإشعارات…');for(const id of ids){const appointment=appointments.find(item=>item._id===id),change=timelinePendingChanges[id];if(!appointment)continue;const changes={service:appointment.service,date:change.date||appointmentDateString(appointment),time:change.time||appointment.time,duration:Number(change.duration||appointment.duration),status:appointment.status,notes:appointment.notes||''};try{await api('/appointments/'+id,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(changes)});reminders.push({appointment,changes});delete timelinePendingChanges[id];await loadAppointments()}catch(e){updateTimelinePendingMessage(`تعذر حفظ التغيير: ${e.message}. صحح الموعد ثم أعد المحاولة.`);button.disabled=false;renderTimeline();return}}await loadOwnerMessages();renderTimeline();updateTimelinePendingMessage('✅ تم حفظ التغييرات وإرسال الإشعارات.');for(const item of reminders)offerWhatsAppReminder(item.appointment,item.changes)}
const days={sunday:'الأحد',monday:'الإثنين',tuesday:'الثلاثاء',wednesday:'الأربعاء',thursday:'الخميس',friday:'الجمعة',saturday:'السبت'};
async function loadHours(){businessSettings=await api('/settings')||{workingHours:{},dateOverrides:[]};businessSettings.dateOverrides=businessSettings.dateOverrides||[];$('workingHours').innerHTML=Object.entries(days).map(([key,label])=>{const h=businessSettings.workingHours?.[key]||{};return`<div class="working-hours-row"><div class="working-hours-day"><strong>${label}</strong><label class="inline-check"><input id="${key}-enabled" type="checkbox" ${h.enabled?'checked':''}> مفتوح</label></div><div class="working-hours-times"><label class="working-hours-time-field">الفتح<input id="${key}-start" type="time" value="${h.start||''}"></label><label class="working-hours-time-field">الاغلاق<input id="${key}-end" type="time" value="${h.end||''}"></label></div></div>`}).join('');renderDateOverrides()}
function collectWorkingHours(){const workingHours={};for(const key of Object.keys(days))workingHours[key]={start:$(`${key}-start`).value,end:$(`${key}-end`).value,enabled:$(`${key}-enabled`).checked,breaks:businessSettings.workingHours?.[key]?.breaks||[]};return workingHours}
async function persistHours(messageText){businessSettings=await api('/settings',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({workingHours:collectWorkingHours(),dateOverrides:businessSettings.dateOverrides||[]})});businessSettings.dateOverrides=businessSettings.dateOverrides||[];renderDateOverrides();if(messageText)msg('dateOverrideMessage',messageText,'success')}
async function saveHours(){await persistHours();alert('تم حفظ ساعات العمل')}
function dateOverrideStart(item){return item.startDate||item.date||''}
function dateOverrideEnd(item){return item.endDate||item.date||''}
function dateOverrideKey(item){return`${dateOverrideStart(item)}|${dateOverrideEnd(item)}`}
function startNewDateOverride(){editingDateOverrideKey='';$('overrideStartDate').value='';$('overrideEndDate').value='';$('overrideEndDate').min=$('overrideStartDate').value||getTodayInJerusalem();$('overrideStart').value='09:00';$('overrideEnd').value='19:00';$('overrideEnabled').checked=true}
function renderDateOverrides(){$('dateOverrides').innerHTML=businessSettings.dateOverrides.length?businessSettings.dateOverrides.slice().sort((a,b)=>dateOverrideStart(a).localeCompare(dateOverrideStart(b))).map(item=>{const start=dateOverrideStart(item),end=dateOverrideEnd(item),label=start===end?start:`${start} – ${end}`;return`<button type="button" class="date-override-item" onclick="editDateOverride('${start}','${end}')"><strong>${safe(label)}</strong><span>${item.enabled?`${safe(item.start)}–${safe(item.end)}`:'مغلق'}</span></button>`}).join(''):'<p class="muted">لا توجد تواريخ خاصة</p>'}
function editDateOverride(startDate,endDate=startDate){const item=businessSettings.dateOverrides.find(value=>dateOverrideStart(value)===startDate&&dateOverrideEnd(value)===endDate);if(!item)return;editingDateOverrideKey=dateOverrideKey(item);$('overrideStartDate').value=startDate;$('overrideEndDate').value=endDate;$('overrideStart').value=item.start||'09:00';$('overrideEnd').value=item.end||'19:00';$('overrideEnabled').checked=item.enabled!==false}
async function saveDateOverride(){const startDate=$('overrideStartDate').value,endDate=$('overrideEndDate').value;if(!startDate||!endDate)return msg('dateOverrideMessage','يرجى اختيار تاريخ البداية والنهاية','error');if(startDate>endDate)return msg('dateOverrideMessage','تاريخ النهاية يجب أن يكون بعد تاريخ البداية','error');const item=startDate===endDate?{date:startDate,start:$('overrideStart').value,end:$('overrideEnd').value,enabled:$('overrideEnabled').checked,breaks:[]}:{startDate,endDate,start:$('overrideStart').value,end:$('overrideEnd').value,enabled:$('overrideEnabled').checked,breaks:[]};let index=editingDateOverrideKey?businessSettings.dateOverrides.findIndex(value=>dateOverrideKey(value)===editingDateOverrideKey):businessSettings.dateOverrides.findIndex(value=>dateOverrideKey(value)===dateOverrideKey(item));const overlaps=startDate!==endDate&&businessSettings.dateOverrides.some((value,itemIndex)=>itemIndex!==index&&value.startDate&&value.endDate&&startDate<=value.endDate&&endDate>=value.startDate);if(overlaps)return msg('dateOverrideMessage','يتداخل هذا النطاق مع نطاق تواريخ محفوظ آخر','error');if(index>=0)businessSettings.dateOverrides[index]=item;else businessSettings.dateOverrides.push(item);editingDateOverrideKey=dateOverrideKey(item);try{await persistHours('تم حفظ ساعات الفترة المحددة')}catch(e){msg('dateOverrideMessage',e.message,'error')}}
async function removeDateOverride(){const key=editingDateOverrideKey||dateOverrideKey({startDate:$('overrideStartDate').value,endDate:$('overrideEndDate').value});const index=businessSettings.dateOverrides.findIndex(item=>dateOverrideKey(item)===key);if(index<0)return msg('dateOverrideMessage','اختر إعداداً محفوظاً لإزالته','error');businessSettings.dateOverrides.splice(index,1);startNewDateOverride();try{await persistHours('تمت إزالة الإعداد الخاص')}catch(e){msg('dateOverrideMessage',e.message,'error')}}
function b64(v){const p='='.repeat((4-v.length%4)%4),raw=atob((v+p).replace(/-/g,'+').replace(/_/g,'/'));return Uint8Array.from([...raw].map(c=>c.charCodeAt(0)))}
async function enablePush(){try{if(!window.isSecureContext)throw new Error('تتطلب الإشعارات اتصال HTTPS آمناً');if(!window.FadilaPwa?.isStandalone())throw new Error('يجب فتح Fadila من الأيقونة على الشاشة الرئيسية');if(!('serviceWorker'in navigator)||!('Notification'in window)||!('PushManager'in window))throw new Error('إصدار الجهاز أو المتصفح لا يدعم الإشعارات');const permission=await Notification.requestPermission();if(permission!=='granted')throw new Error('يرجى السماح بالإشعارات من إعدادات الجهاز');const reg=await navigator.serviceWorker.ready,{publicKey}=await api('/push/public-key');if(!publicKey)throw new Error('لم يتم إعداد مفاتيح الإشعارات على الخادم بعد');let sub=await reg.pushManager.getSubscription();sub=sub||await reg.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:b64(publicKey)});await api('/push/subscribe',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({subscription:sub})});$('notificationState').textContent='✅ الإشعارات مفعّلة';$('enableNotifications').classList.add('hidden')}catch(e){console.error('Push setup failed:',e);$('notificationState').textContent=e.message||'تعذر تفعيل الإشعارات على هذا الجهاز'}}
async function syncExistingOwnerPush(){if(existingPushSynced)return;try{if(!('serviceWorker'in navigator)||!('Notification'in window)||Notification.permission!=='granted')return;const reg=await navigator.serviceWorker.ready,subscription=await reg.pushManager.getSubscription();if(subscription)await api('/push/subscribe',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({subscription})});existingPushSynced=true}catch(e){console.error('Owner push account sync failed:',e)}}
async function logoutOwner(){try{if('serviceWorker'in navigator){const reg=await navigator.serviceWorker.ready,subscription=await reg.pushManager.getSubscription();if(subscription)await fetch(API+'/push/subscribe',{method:'DELETE',headers:{Authorization:`Bearer ${token}`,'Content-Type':'application/json'},body:JSON.stringify({endpoint:subscription.endpoint}),keepalive:true})}}catch(e){console.error('Owner push logout cleanup failed:',e)}finally{localStorage.removeItem('token');location.href='index.html'}}
