async function sendCustomerNotification(){try{const selected=$('notificationCustomer').value,title=$('notificationTitle').value.trim(),body=$('notificationBody').value.trim(),sendToAll=selected==='__all__';if(!selected||!title||!body)throw new Error('يرجى اختيار المستلم وكتابة العنوان والرسالة');if(sendToAll&&!confirm('هل تريد إرسال الإشعار إلى جميع الزبائن النشطين؟'))return;$('sendCustomerNotification').disabled=true;const data=await api('/push/send',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({customerId:sendToAll?null:selected,sendToAll,title,body})});if(data.sent>0){const text=sendToAll?`✅ تم إرسال الإشعار إلى ${data.sent} من أجهزة الزبائن`:`✅ تم إرسال الإشعار إلى ${data.sent} من الأجهزة`;msg('sendNotificationMessage',text,'success');$('notificationTitle').value='';$('notificationBody').value=''}else{msg('sendNotificationMessage',sendToAll?'لا توجد أجهزة مسجلة لدى الزبائن':'لا يوجد جهاز مسجل للإشعارات لدى هذا الزبون','error')}}catch(e){msg('sendNotificationMessage',e.message,'error')}finally{$('sendCustomerNotification').disabled=false}}
function messageAppointmentId(item){if(item.appointment)return String(item.appointment);const match=String(item.tag||'').match(/^(?:change-request-|new-|owner-reminder-|owner-hour-reminder-)([a-f\d]{24})(?:-|$)/i);return match?.[1]||''}
function isCurrentChangeRequestMessage(item,allMessages){const id=messageAppointmentId(item),appointment=appointments.find(a=>a._id===id);if(!id||appointment?.changeRequest?.status!=='pending')return false;const currentTag=appointment.changeRequest.notificationTag;if(currentTag)return item.tag===currentTag;const newest=allMessages.find(message=>messageAppointmentId(message)===id);return newest?._id===item._id}
function isPendingBookingMessage(item){const id=messageAppointmentId(item),appointment=appointments.find(a=>a._id===id);return /^new-[a-f\d]{24}$/i.test(String(item.tag||''))&&appointment?.status==='pending'}
async function approvePendingAppointment(id){const appointment=appointments.find(item=>item._id===id);if(!appointment||!confirm(`تأكيد موعد ${appointment.customerName}؟`))return;try{const date=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Jerusalem'}).format(new Date(appointment.date));await api('/appointments/'+id,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({service:appointment.service,date,time:appointment.time,status:'confirmed',notes:appointment.notes||''})});await loadAppointments();await loadOwnerMessages()}catch(e){alert(e.message);openPartialChangeEdit(id)}}
function appointmentWhatsAppButton(id){const appointment=appointments.find(item=>item._id===id);if(!appointment?.customerPhone)return'';const phone=String(appointment.customerPhone).replace(/\D/g,'').replace(/^0/,'972');const date=new Date(appointment.date).toLocaleDateString('ar',{timeZone:'Asia/Jerusalem'});const reminder=`مرحباً ${appointment.customerName} 👋\nنذكّرك بموعدك في Fadila Barber 💈\nالخدمة: ${appointment.service}\nالتاريخ: ${date}\nالساعة: ${appointment.time}\nننتظرك بكل سرور 😊`;return`<a class="message-whatsapp-button" href="https://wa.me/${phone}?text=${encodeURIComponent(reminder)}" target="_blank" rel="noopener noreferrer">إرسال تذكير عبر واتساب</a>`}
function ownerMessageActions(item,allMessages){const id=messageAppointmentId(item),isChangeRequest=isCurrentChangeRequestMessage(item,allMessages),isPendingBooking=isPendingBookingMessage(item);let actionButtons='';if(isChangeRequest)actionButtons=`<button type="button" onclick="resolveChangeRequest('${id}','approved')">موافقة وتحديث</button><button type="button" class="secondary" onclick="openMessageAppointmentEditor('${id}','${item._id}')">تعديل الموعد</button>`;else if(isPendingBooking)actionButtons=`<button type="button" onclick="approvePendingAppointment('${id}')">موافقة على الموعد</button><button type="button" class="secondary" onclick="openMessageAppointmentEditor('${id}','${item._id}')">تعديل الموعد</button>`;return`<div class="message-actions">${actionButtons}${appointmentWhatsAppButton(id)}<button type="button" class="danger message-delete-button" onclick="deleteOwnerMessage('${item._id}')">حذف الرسالة</button></div>${isChangeRequest||isPendingBooking?`<div id="message-appointment-editor-${item._id}" class="message-appointment-editor hidden"></div>`:''}`}
async function deleteOwnerMessage(id){if(!confirm('هل تريد حذف هذه الرسالة؟'))return;try{await api('/messages/'+id,{method:'DELETE'});await loadOwnerMessages()}catch(e){alert(e.message)}}
async function deleteTreatedMessages(){if(!confirm('هل تريد حذف جميع رسائل طلبات التعديل التي تمت معالجتها؟'))return;try{const result=await api('/messages/treated/all',{method:'DELETE'});await loadOwnerMessages();if(!result.deleted)alert('لا توجد رسائل معالجة للحذف')}catch(e){alert(e.message)}}
async function loadFeedback(){
  try{
    const d=await api('/feedback');ownerFeedback=d.data;renderOwnerOverview();
    $('ownerFeedbackSummary').textContent=d.ratingCount?`متوسط التقييم ${Number(d.averageRating).toFixed(1)} ★★★★★ · ${d.ratingCount} تقييم`:'لا توجد تقييمات منشورة بعد';
    $('ownerFeedbackList').innerHTML=d.data.length?d.data.map(item=>`<article class="owner-feedback-item"><div class="owner-feedback-item-heading"><strong>${safe(item.displayName)}</strong><span aria-label="${item.rating} من 5">${'★'.repeat(item.rating)}${'☆'.repeat(5-item.rating)}</span><time>${new Date(item.createdAt).toLocaleDateString('ar',{timeZone:'Asia/Jerusalem'})}</time></div><p>${safe(item.text)}</p><button type="button" class="danger compact" onclick="deleteFeedback('${item._id}')">حذف التقييم</button></article>`).join(''):'<p class="muted">لا توجد تقييمات منشورة بعد.</p>';
  }catch(error){console.error('Feedback management load failed:',error);$('ownerFeedbackSummary').textContent='تعذر تحميل التقييمات';$('ownerFeedbackList').innerHTML='';renderOwnerOverview()}
}
async function deleteFeedback(id){
  if(!confirm('هل تريد حذف هذا التقييم؟'))return;
  try{await api(`/feedback/${encodeURIComponent(id)}`,{method:'DELETE'});msg('ownerFeedbackMessage','تم حذف التقييم','success');await loadFeedback()}
  catch(error){msg('ownerFeedbackMessage',error.message,'error')}
}
async function loadOwnerMessages(){try{await syncExistingOwnerPush();const d=await api('/messages');ownerMessages=d.data;renderOwnerOverview();$('ownerMessagesBadge').textContent=d.unreadCount>99?'99+':String(d.unreadCount);$('ownerMessagesBadge').classList.toggle('hidden',!d.unreadCount);$('ownerMessagesButton').setAttribute('aria-label',`الرسائل، ${d.unreadCount} غير مقروءة`);$('messageBulkBar').classList.toggle('hidden',!d.data.length);$('selectAllMessages').checked=false;$('ownerMessagesList').innerHTML=d.data.length?d.data.map(item=>`<article class="message-item ${item.readAt?'':'unread'}"><label class="message-select"><input class="message-checkbox" type="checkbox" value="${item._id}" onchange="updateMessageSelection()"><span class="sr-only">اختيار الرسالة</span></label><div><h3>${safe(item.title)}</h3><time>${new Date(item.createdAt).toLocaleString('ar',{timeZone:'Asia/Jerusalem'})}</time></div><p>${safe(item.body)}</p>${ownerMessageActions(item,d.data)}</article>`).join(''):'<p class="muted empty-messages">لا توجد رسائل بعد</p>';updateMessageSelection()}catch(e){console.error('Owner messages load failed:',e)}}
function selectedMessageIds(){return[...document.querySelectorAll('.message-checkbox:checked')].map(input=>input.value)}
function updateMessageSelection(){const selected=selectedMessageIds(),total=document.querySelectorAll('.message-checkbox').length;$('selectedMessagesCount').textContent=`${selected.length} محددة`;$('deleteSelectedMessages').disabled=!selected.length;$('selectAllMessages').checked=total>0&&selected.length===total;$('selectAllMessages').indeterminate=selected.length>0&&selected.length<total}
function toggleAllMessages(){document.querySelectorAll('.message-checkbox').forEach(input=>input.checked=$('selectAllMessages').checked);updateMessageSelection()}
async function deleteSelectedMessages(){const ids=selectedMessageIds();if(!ids.length||!confirm(`حذف ${ids.length} رسائل محددة؟`))return;try{await api('/messages',{method:'DELETE',headers:{'Content-Type':'application/json'},body:JSON.stringify({ids})});await loadOwnerMessages()}catch(e){alert(e.message)}}
async function refreshOwnerMessages(){await loadAppointments();await loadOwnerMessages();await loadFeedback()}
async function refreshOwnerData(){const button=$('ownerRefreshButton');button.disabled=true;button.classList.add('is-refreshing');try{await Promise.all([loadCustomers(),loadServices(),loadHours(),loadFeedback()]);await loadAppointments();await loadOwnerMessages()}catch(e){alert(e.message)}finally{button.disabled=false;button.classList.remove('is-refreshing')}}
async function openOwnerMessages(){closeOwnerNavigation();await refreshOwnerMessages();$('ownerMessagesPanel').classList.remove('hidden');document.body.classList.add('messages-open');try{await api('/messages/read-all',{method:'PUT'});$('ownerMessagesBadge').classList.add('hidden');$('ownerMessagesList').querySelectorAll('.unread').forEach(item=>item.classList.remove('unread'))}catch(e){console.error(e)}}
function closeOwnerMessages(){$('ownerMessagesPanel').classList.add('hidden');document.body.classList.remove('messages-open')}
function showOwnerApp(){const welcome=$('ownerWelcomeView');welcome.classList.add('welcome-leaving');setTimeout(()=>{welcome.classList.add('hidden');$('ownerAppContent').classList.remove('hidden')},360)}
function setupCollapsibleSections(){document.querySelectorAll('.collapsible-card').forEach(card=>{const key=`owner-section-${card.dataset.section}`,button=card.querySelector('.collapse-button');const setCollapsed=collapsed=>{card.classList.toggle('is-collapsed',collapsed);button.textContent=collapsed?'+':'−';button.setAttribute('aria-expanded',String(!collapsed));button.setAttribute('aria-label',`${collapsed?'فتح':'طي'} ${card.querySelector('h2').textContent}`)};setCollapsed(localStorage.getItem(key)==='collapsed');button.addEventListener('click',()=>{const collapsed=!card.classList.contains('is-collapsed');setCollapsed(collapsed);localStorage.setItem(key,collapsed?'collapsed':'open')})})}

let galleryAdminItems=[];
function renderOwnerGallery(){
 const container=$('galleryAdminList');
 if(!container)return;
 container.replaceChildren();
 if(!galleryAdminItems.length){const empty=document.createElement('p');empty.className='owner-gallery-empty muted';empty.textContent='لا توجد صور في المعرض بعد. أضف صوراً لتظهر للعملاء.';container.appendChild(empty);return}
 galleryAdminItems.forEach((item,index)=>{
  const card=document.createElement('article');card.className='owner-gallery-item';
  const image=document.createElement('img');image.alt='صورة '+(index+1)+' من أعمال المحل';image.loading='lazy';image.decoding='async';
  image.src=/^data:image\/(?:jpe?g|png|webp);base64,[A-Za-z0-9+/]+={0,2}$/.test(String(item.image||''))?item.image:'';
  const controls=document.createElement('div');controls.className='owner-gallery-controls';
  const remove=document.createElement('button');remove.type='button';remove.className='danger compact';remove.dataset.galleryDelete=String(item._id);remove.textContent='حذف';
  const position=document.createElement('span');position.className='owner-gallery-position';position.textContent='الصورة '+(index+1);
  const up=document.createElement('button');up.type='button';up.className='secondary compact';up.dataset.galleryMove=String(item._id);up.dataset.direction='-1';up.disabled=index===0;up.setAttribute('aria-label','تحريك الصورة للأعلى');up.textContent='↑';
  const down=document.createElement('button');down.type='button';down.className='secondary compact';down.dataset.galleryMove=String(item._id);down.dataset.direction='1';down.disabled=index===galleryAdminItems.length-1;down.setAttribute('aria-label','تحريك الصورة للأسفل');down.textContent='↓';
  controls.append(remove,position,up,down);card.append(image,controls);container.appendChild(card);
 });
}
async function loadOwnerGallery(){
 try{galleryAdminItems=await api('/gallery');if(!Array.isArray(galleryAdminItems))galleryAdminItems=[];renderOwnerGallery()}
 catch(error){msg('galleryAdminMessage',error.message,'error')}
}
async function saveOwnerGalleryOrder(){
 try{await api('/gallery/reorder',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({imageIds:galleryAdminItems.map(item=>String(item._id))})});msg('galleryAdminMessage','تم حفظ ترتيب الصور','success')}
 catch(error){msg('galleryAdminMessage',error.message,'error');await loadOwnerGallery()}
}
async function uploadOwnerGalleryFiles(fileList){
 const files=Array.from(fileList||[]);if(!files.length)return;
 const invalid=files.find(file=>!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>8*1024*1024);
 if(invalid){msg('galleryAdminMessage','اختر صور JPG أو PNG أو WebP بحجم لا يتجاوز 8 ميغابايت للصورة','error');return}
 const button=$('galleryUploadButton');button.disabled=true;
 try{
  for(let i=0;i<files.length;i++){msg('galleryAdminMessage','جارٍ رفع الصورة '+(i+1)+' من '+files.length+'...');const form=new FormData();form.append('image',files[i]);await api('/gallery',{method:'POST',body:form})}
  await loadOwnerGallery();msg('galleryAdminMessage','تمت إضافة الصور إلى المعرض','success')
 }catch(error){msg('galleryAdminMessage',error.message,'error')}
 finally{button.disabled=false;$('galleryUploadInput').value=''}
}
async function deleteOwnerGalleryImage(id){
 const item=galleryAdminItems.find(image=>String(image._id)===String(id));if(!item||!confirm('هل تريد حذف هذه الصورة من المعرض؟'))return;
 try{await api('/gallery/'+encodeURIComponent(id),{method:'DELETE'});galleryAdminItems=galleryAdminItems.filter(image=>String(image._id)!==String(id));renderOwnerGallery();await saveOwnerGalleryOrder();msg('galleryAdminMessage','تم حذف الصورة','success')}
 catch(error){msg('galleryAdminMessage',error.message,'error')}
}
async function moveOwnerGalleryImage(id,direction){
 const from=galleryAdminItems.findIndex(image=>String(image._id)===String(id)),to=from+Number(direction);if(from<0||to<0||to>=galleryAdminItems.length)return;
 [galleryAdminItems[from],galleryAdminItems[to]]=[galleryAdminItems[to],galleryAdminItems[from]];renderOwnerGallery();await saveOwnerGalleryOrder()
}
function closeOwnerNavigation(){
 $('ownerNavDrawer').classList.remove('is-open');$('ownerNavDrawer').setAttribute('aria-hidden','true');$('ownerNavBackdrop').classList.add('hidden');$('ownerMenuButton').setAttribute('aria-expanded','false');document.body.classList.remove('owner-nav-open')
}
function openOwnerNavigation(){
 $('ownerNavDrawer').classList.add('is-open');$('ownerNavDrawer').setAttribute('aria-hidden','false');$('ownerNavBackdrop').classList.remove('hidden');$('ownerMenuButton').setAttribute('aria-expanded','true');document.body.classList.add('owner-nav-open')
}
function selectOwnerPanel(name){
 const panel=document.querySelector('[data-owner-panel="'+name+'"]');if(!panel)return;
 document.querySelectorAll('[data-owner-panel]').forEach(item=>{const isActive=item===panel;item.hidden=!isActive;item.classList.toggle('hidden',!isActive)});
 panel.classList.remove('is-collapsed');const collapseButton=panel.querySelector('.collapse-button');if(collapseButton){collapseButton.textContent='−';collapseButton.setAttribute('aria-expanded','true');localStorage.setItem('owner-section-'+name,'open')}
 document.querySelectorAll('[data-owner-target]').forEach(button=>{if(button.dataset.ownerTarget===name)button.setAttribute('aria-current','page');else button.removeAttribute('aria-current')});
 localStorage.setItem('owner-active-panel',name);closeOwnerNavigation();window.scrollTo({top:0,behavior:'smooth'});
 if(name==='gallery')loadOwnerGallery()
}
function setupOwnerNavigation(){
 $('ownerMenuButton').addEventListener('click',()=>{if($('ownerNavDrawer').classList.contains('is-open'))closeOwnerNavigation();else openOwnerNavigation()});
 $('ownerNavClose').addEventListener('click',closeOwnerNavigation);$('ownerNavBackdrop').addEventListener('click',closeOwnerNavigation);
 $('ownerNavDrawer').addEventListener('click',event=>{const button=event.target.closest('[data-owner-target]');if(button)selectOwnerPanel(button.dataset.ownerTarget)});
 $('ownerOverview').addEventListener('click',event=>{const button=event.target.closest('[data-overview-target]');if(button)selectOwnerPanel(button.dataset.overviewTarget)});
 document.addEventListener('keydown',event=>{if(event.key==='Escape')closeOwnerNavigation()});
 selectOwnerPanel('overview')
}
function setupOwnerGallery(){
 $('galleryUploadButton').addEventListener('click',()=>$('galleryUploadInput').click());
 $('galleryUploadInput').addEventListener('change',event=>uploadOwnerGalleryFiles(event.target.files));
 $('galleryAdminList').addEventListener('click',event=>{const remove=event.target.closest('[data-gallery-delete]'),move=event.target.closest('[data-gallery-move]');if(remove)deleteOwnerGalleryImage(remove.dataset.galleryDelete);else if(move)moveOwnerGalleryImage(move.dataset.galleryMove,move.dataset.direction)})
}
